import assert from 'node:assert/strict';
import express from 'express';
import ExcelJS from 'exceljs';
import service from '../../src/vercel.js';
import prisma from '../../src/db/prisma.js';
const app=express();app.use(service);const server=app.listen(0,'127.0.0.1');await new Promise(resolve=>server.once('listening',resolve));const base=`http://127.0.0.1:${server.address().port}/api`;let token;
async function req(path,method='GET',body,auth=token){const response=await fetch(base+path,{method,headers:{'Content-Type':'application/json',Authorization:'Bearer '+auth},body:body===undefined?undefined:JSON.stringify(body)});return {status:response.status,data:await response.json()};}
async function upload(path,bytes){const response=await fetch(base+path,{method:'POST',headers:{'Content-Type':'application/octet-stream',Authorization:'Bearer '+token},body:bytes});return {status:response.status,data:await response.json()};}
const ok=r=>{assert(r.status<300,JSON.stringify(r));return r.data;};

function makeSheet(book,name,headersAt=4){const s=book.addWorksheet(name);s.getCell('E2').value='Employee / 9999 EGP per hour';for(const [col,text]of Object.entries({B:'NO',C:'Start Date',D:'Name',E:'Phone Number',F:'COURSE',G:'End Date',H:'Duration',I:'Currency',J:'Amount',K:'Payment',L:'Books'}))s.getCell(col+headersAt).value=text;return s;}
async function workbook(){const book=new ExcelJS.Workbook(),s=makeSheet(book,'مي عادل');const values={C5:'11/9/20226',D5:'Different spelling existing student',E5:'+20 1000000000',F5:'Private KET',G5:'21/09/2026',H5:'18:30 Hrs / 999 EGP',I5:'EGP',J5:7000,K5:'IGNORE',L5:'IGNORE',D6:'Second student',E6:'01011111111'};for(const[c,v]of Object.entries(values))s.getCell(c).value=v;for(const col of ['C','F','G','H','I','J'])s.mergeCells(`${col}5:${col}6`);s.getCell('B7').value=500;
const t=makeSheet(book,'New teacher',5);for(const[c,v]of Object.entries({C6:'02/11/2026',D6:'Free new student',E6:'01022222222',F6:'Private IELTS',H6:'20 Hrs / 140 EGP',I6:'EGP',J6:'FREE',K6:1}))t.getCell(c).value=v;return Buffer.from(await book.xlsx.writeBuffer());}
try{
 token=ok(await req('/auth/login','POST',{username:'main-admin',password:'IsolatedDemoTest!123'})).token;const junior=ok(await req('/auth/login','POST',{username:'Joe',password:'IsolatedDemoTest!123'})).token;
 const existing=await prisma.student.create({data:{name:'الطالب الموجود',mobile:'01000000000'}});
 const parent=ok(await req('/courses','POST',{name:'Private import academy',code:'PRIVATE-BULK',isPrivate:true}));const path='/imports/'+parent.id+'/private';const bytes=await workbook();
 const forbidden=await fetch(base+path+'/preview',{method:'POST',headers:{Authorization:'Bearer '+junior,'Content-Type':'application/octet-stream'},body:bytes});assert.equal(forbidden.status,403);
 let preview=ok(await upload(path+'/preview',bytes));assert.equal(preview.rows.length,3);assert.equal(preview.sheets.length,2);assert.equal(preview.rows[0].startDate,'2026-09-11');assert.equal(preview.rows[0].hours,18.5);assert.equal(preview.rows[1].amount,7000);assert(preview.rows[0].notes.some(n=>n.includes('20226')));assert.equal(preview.rows[0].matches[0].id,existing.id);
 const edits=Object.fromEntries(preview.rows.map((r,i)=>[r.id,{...r,branch:'MIAMI',hourlyRate:100+i*50}]));preview=ok(await req(path+'/review','POST',{previewToken:preview.previewToken,edits}));assert(preview.rows.every(r=>!r.errors.length));
 const employees={'0':{mode:'existing',employeeId:'demo-instructor-1',hourlyRate:'100'},'1':{mode:'new',name:'موظف جديد',employeeId:'NEW-PRIVATE-EMP',hourlyRate:'120'}};
 const payload={previewToken:preview.previewToken,rowIds:preview.rows.map(r=>r.id),employees,students:{}};
 const before=await prisma.cycle.count();const invalidRate=ok(await req(path+'/review','POST',{previewToken:preview.previewToken,edits:{[preview.rows[2].id]:{hourlyRate:''}}}));assert.equal((await req(path+'/commit','POST',{...payload,previewToken:invalidRate.previewToken})).status,400);assert.equal(await prisma.cycle.count(),before);assert.equal(await prisma.instructor.count({where:{employeeId:'NEW-PRIVATE-EMP'}}),0);
 const result=ok(await req(path+'/commit','POST',payload));assert.equal(result.cycles.length,3);assert.equal(result.created,2);assert.equal(result.reused,1);
 const cycles=await prisma.cycle.findMany({where:{parentCourseId:parent.id},include:{instructors:true,enrollments:{include:{student:true,bookPayments:true,payments:true}},payrollEarnings:true},orderBy:{cycleNumber:'asc'}});
 assert.equal(cycles[0].courseFee,7000);assert.equal(cycles[1].courseFee,7000);assert.equal(cycles[0].enrollments[0].studentId,existing.id);assert.equal(cycles[0].totalHours,18.5);assert.equal(cycles[0].instructors[0].hourlyRate,100);assert.equal(cycles[0].payrollEarnings[0].amountMinor,185000n);assert.equal(cycles[1].instructors[0].hourlyRate,150);assert.equal(cycles[1].payrollEarnings[0].amountMinor,277500n);assert(cycles[0].isFinished);assert(!cycles[2].isFinished);assert.equal(cycles[2].enrollments[0].customFee,0);assert.equal(cycles[2].enrollments[0].amountPaid,0);assert(cycles.every(c=>c.enrollments.length===1&&c.enrollments[0].bookPayments.length===0));assert.equal(cycles[0].enrollments[0].payments[0].paymentMethod,'UNSPECIFIED');
 assert.equal((await req(path+'/commit','POST',payload)).status,409);assert.equal((ok(await upload(path+'/preview',bytes))).rows.filter(r=>r.alreadyImported).length,3);
 // Multiple matches are never silently merged. A stale phone match cannot change unnoticed.
 const extra=await prisma.student.create({data:{name:'نفس الهاتف',mobile:existing.mobile}});const freshParent=ok(await req('/courses','POST',{name:'Another private umbrella',code:'PRIVATE-BULK-2',isPrivate:true}));const other='/imports/'+freshParent.id+'/private';let conflict=ok(await upload(other+'/preview',bytes));conflict=ok(await req(other+'/review','POST',{previewToken:conflict.previewToken,edits}));const choicePayload={...payload,previewToken:conflict.previewToken,rowIds:[conflict.rows[0].id]};assert.equal((await req(other+'/commit','POST',choicePayload)).status,400);ok(await req(other+'/commit','POST',{...choicePayload,students:{[conflict.rows[0].id]:extra.id}}));
 // A changed phone creates a fresh profile, even when the name is identical.
 const editRow=conflict.rows[1];let changed=ok(await req(other+'/review','POST',{previewToken:conflict.previewToken,edits:{[editRow.id]:{name:existing.name,mobile:'01033333333',branch:'MIAMI'}}}));const next=ok(await req(other+'/commit','POST',{...payload,previewToken:changed.previewToken,rowIds:[editRow.id]}));const newCycle=await prisma.cycle.findUnique({where:{id:next.cycles[0].id},include:{enrollments:true}});assert.notEqual(newCycle.enrollments[0].studentId,existing.id);
 assert.equal((await req('/imports/course-ket/private/preview','POST',{})).status,404);
 console.log('PASS: bulk private workbook sheets, merged tuition, hours, dates, employee mapping, phone identity, paid/exempt ledger, privacy and atomic replay guards');
}finally{await new Promise(resolve=>server.close(resolve));await prisma.$disconnect();}
